CREATE OR REPLACE FUNCTION b_ledger_apply_fn() RETURNS trigger AS $$ BEGIN UPDATE b_participants SET balance=balance+NEW.delta WHERE id=NEW.participantId; RETURN NEW; END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS b_ledger_apply ON b_ledger; CREATE TRIGGER b_ledger_apply AFTER INSERT ON b_ledger FOR EACH ROW EXECUTE FUNCTION b_ledger_apply_fn();
